     1|/**
     2| * IVX Autonomous Scheduler API (owner-only) — BLOCK 41.
     3| *
     4| * Surfaces + controls the durable scheduler that automatically runs the daily
     5| * self-audit + architecture-drift detection and wires each result into the
     6| * unified memory + executive action loop:
     7| *   GET  /api/ivx/scheduler            → scheduler + per-job state (last/next run)
     8| *   POST /api/ivx/scheduler/run-now    → run due jobs now (or a specific {job})
     9| *   POST /api/ivx/scheduler/enable     → enable/disable the scheduler ({enabled})
    10| *
    11| * Owner-gated via the same guard as the rest of the IVX developer surface.
    12| */
    13|import {
    14|  getSchedulerState,
    15|  runDueJobs,
    16|  runScheduledJob,
    17|  setSchedulerEnabled,
    18|  SCHEDULED_JOB_KINDS,
    19|  type ScheduledJobKind,
    20|} from '../services/ivx-autonomous-scheduler';
    21|import { assertIVXOwnerOnly, ownerOnlyJson, ownerOnlyOptions } from './owner-only';
    22|
    23|export const OPTIONS = (): Response => ownerOnlyOptions();
    24|
    25|async function requireOwner(request: Request): Promise<{ ok: true } | { ok: false; response: Response }> {
    26|  try {
    27|    const owner = await assertIVXOwnerOnly(request);
    28|    if (!owner.userId) {
    29|      return { ok: false, response: ownerOnlyJson({ ok: false, error: 'IVX owner authentication required.' }, 401) };
    30|    }
    31|    return { ok: true };
    32|  } catch (error) {
    33|    const message = error instanceof Error ? error.message : 'IVX owner authentication required.';
    34|    const status = message.toLowerCase().includes('missing bearer') ? 401 : 403;
    35|    return { ok: false, response: ownerOnlyJson({ ok: false, error: message }, status) };
    36|  }
    37|}
    38|
    39|function isJobKind(value: unknown): value is ScheduledJobKind {
    40|  return typeof value === 'string' && (SCHEDULED_JOB_KINDS as readonly string[]).includes(value);
    41|}
    42|
    43|async function parseBody(request: Request): Promise<Record<string, unknown>> {
    44|  try {
    45|    const body = await request.json();
    46|    return body && typeof body === 'object' ? (body as Record<string, unknown>) : {};
    47|  } catch {
    48|    return {};
    49|  }
    50|}
    51|
    52|/** GET / — scheduler + per-job state. */
    53|export async function handleSchedulerStatusRequest(request: Request): Promise<Response> {
    54|  const auth = await requireOwner(request);
    55|  if (!auth.ok) return auth.response;
    56|  try {
    57|    const state = await getSchedulerState();
    58|    return ownerOnlyJson({ ok: true, scheduler: state });
    59|  } catch (error) {
    60|    return ownerOnlyJson({ ok: false, error: error instanceof Error ? error.message : 'Failed to load scheduler state.' }, 500);
    61|  }
    62|}
    63|
    64|/** POST /run-now — run due jobs now, or a specific {job} kind. */
    65|export async function handleSchedulerRunNowRequest(request: Request): Promise<Response> {
    66|  const auth = await requireOwner(request);
    67|  if (!auth.ok) return auth.response;
    68|  try {
    69|    const body = await parseBody(request);
    70|    if (body.job !== undefined) {
    71|      if (!isJobKind(body.job)) {
    72|        return ownerOnlyJson({ ok: false, error: `Unknown job. Valid jobs: ${SCHEDULED_JOB_KINDS.join(', ')}.` }, 400);
    73|      }
    74|      const result = await runScheduledJob(body.job);
    75|      const state = await getSchedulerState();
    76|      return ownerOnlyJson({ ok: true, ran: [result], scheduler: state });
    77|    }
    78|    const results = await runDueJobs();
    79|    const state = await getSchedulerState();
    80|    return ownerOnlyJson({ ok: true, ran: results, scheduler: state });
    81|  } catch (error) {
    82|    return ownerOnlyJson({ ok: false, error: error instanceof Error ? error.message : 'Failed to run scheduled jobs.' }, 500);
    83|  }
    84|}
    85|
    86|/** POST /enable — enable/disable the scheduler ({enabled:boolean}). */
    87|export async function handleSchedulerEnableRequest(request: Request): Promise<Response> {
    88|  const auth = await requireOwner(request);
    89|  if (!auth.ok) return auth.response;
    90|  try {
    91|    const body = await parseBody(request);
    92|    const enabled = body.enabled !== false; // default to enabling unless explicitly false
    93|    const state = await setSchedulerEnabled(enabled);
    94|    return ownerOnlyJson({ ok: true, scheduler: state });
    95|  } catch (error) {
    96|    return ownerOnlyJson({ ok: false, error: error instanceof Error ? error.message : 'Failed to update scheduler.' }, 500);
    97|  }
